const stadiumSlugToTeam: Record<string, TeamId> = {
  "kyujo-guide-tokyo-dome": "giants",
  "kyujo-guide-jingu": "swallows",
  "kyujo-guide-yokohama-stadium": "baystars",
  "kyujo-guide-vantelin-dome": "dragons",
  "kyujo-guide-koshien": "tigers",
  "kyujo-guide-mazda-stadium": "carp",
  "kyujo-guide-escon-field": "fighters",
  "kyujo-guide-rakuten-park-miyagi": "eagles",
  "kyujo-guide-belluna-dome": "lions",
  "kyujo-guide-zozo-marine": "marines",
  "kyujo-guide-kyocera-dome": "buffaloes",
  "kyujo-guide-mizuho-paypay-dome": "hawks",
};

export function getTeamForSlug(slug: string): TeamId | null {
  if (slug in stadiumSlugToTeam) return stadiumSlugToTeam[slug];
  const m = slug.match(/^(?:fanclub|events)-guide-([a-z]+)-2026$/);
  if (m && m[1] in teams) return m[1] as TeamId;
  return null;
}

export function getRelatedPostsByTeam(team: TeamId, excludeSlug: string): BlogPost[] {
  return posts.filter((p) => p.slug !== excludeSlug && getTeamForSlug(p.slug) === team);
}

